import os,resource,signal,pathlib,json,hashlib,base64,sys
os.sched_setaffinity(0,{min(os.sched_getaffinity(0))});resource.setrlimit(resource.RLIMIT_AS,(1024**3,1024**3));resource.setrlimit(resource.RLIMIT_CPU,(60,60));signal.alarm(90)
R=pathlib.Path('/srv/android/asus-full-system-observer-preparation-20261106')
PAYLOAD = {'source/resolve_fs_config.cpp': '', 'source/resolve_contexts.c': '', 'scripts/capture_expectations.py': ''}
for n,data in PAYLOAD.items():
 p=R/n;assert not p.exists();p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(data))
sys.path.insert(0,str(R/'scripts'))
from engine import pinned_runtime,command,environment
pin=pinned_runtime();raw=R/'fixture/system.raw';initial=json.loads((R/'fixture/setup-result.json').read_text())
final_hash=hashlib.sha256(raw.read_bytes()).hexdigest();assert final_hash==initial['raw_sha256']
fsck=command([str(R/'immutable/bin/e2fsck'),'-f','-n',str(raw)],R/'fixture/fsck-final-strict.log',environment(R/'fixture'));assert fsck==dict(exit=0,timed_out=False)
# Refusal of the production expectation publisher uses only already owned synthetic receipts.
a=json.loads((R/'fixture/owner/strict-r2/positive/admission.json').read_text());res=json.loads(pathlib.Path(a['resolved_metadata']['path']).read_text())['resolution_receipts'][0]
cmd=[sys.executable,'-B',str(R/'scripts/capture_expectations.py')]
for name,ref in [('complete',a['complete']),('source-binding',a['source_binding']),('resolution',res)]:cmd+=['--'+name,ref['path'],'--'+name+'-pin',ref['sha256']]
publisher=command(cmd,R/'fixture/publisher-refusal.log',None);assert publisher==dict(exit=2,timed_out=False)
logs={}
for name in ['positive','wrong-hash','wrong-metadata','strict-positive','strict-wrong-hash','strict-wrong-metadata']:
 root=R/'runs'/name
 logs[name]={n:(root/n).read_text()for n in ['generation.json','result.json','serial.log','compile.log','expectations.h','headers.d']}
files={str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest()for d in ['source','scripts','tests']for p in (R/d).glob('*')if p.is_file()}
result=dict(audit_passed=True,remote_root=str(R),immutable_pins_sha256=pin,all_2368_immutable_files_reverified=True,
            fixture_final_sha256=final_hash,separate_final_host_fsck=fsck,publisher_refused_fixture=publisher,
            source_pins=files,logs=logs,
            fixture_logs={p.name:p.read_text()for p in (R/'fixture').glob('*.log')},
            tool_copy_receipts_sha256=hashlib.sha256((R/'copy-receipts.json').read_bytes()).hexdigest(),
            actual_product_read_or_mounted=False,production_input_emitted=False,physical_GO=False)
(R/'audit.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
